// Builds one technician's schedule email from a row of lamig.claim_schedule_emails().
const r = $input.item.json;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const jobs = Array.isArray(r.jobs) ? r.jobs : [];
const first = String(r.technician_name || '').split(' ')[0] || 'there';
const day = r.date_label;

const subject = r.is_update
  ? `Updated schedule for ${day}`
  : `Your jobs for ${day} (${jobs.length} job${jobs.length === 1 ? '' : 's'})`;

const intro = jobs.length === 0
  ? `Hi ${first}, your jobs for ${day} were moved or cancelled. You have no jobs that day.`
  : r.is_update
    ? `Hi ${first}, your schedule for ${day} changed. Here is the latest list.`
    : `Hi ${first}, here are your jobs for ${day}.`;

const mapUrl = (a) => 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(a);
const cards = jobs.map((j) => `
  <div style="border:1px solid #c3d6df;border-radius:14px;padding:14px 16px;margin-top:10px">
    <p style="margin:0;font-size:20px;font-weight:bold;color:#10303b">${esc(j.time)} <span style="font-size:14px;font-weight:normal;color:#4f6b78">until ${esc(j.end)}</span></p>
    <p style="margin:6px 0 0;font-weight:bold">${esc(j.service)}</p>
    <p style="margin:2px 0 0">${esc(j.customer)}, <a href="tel:${esc(j.phone)}" style="color:#10303b">${esc(j.phone)}</a></p>
    <p style="margin:2px 0 0"><a href="${mapUrl(j.address)}" style="color:#10303b">${esc(j.address)}</a></p>
    ${j.notes ? `<p style="margin:6px 0 0;background:#eef4f7;border-radius:8px;padding:6px 10px">Note: ${esc(j.notes)}</p>` : ''}
    <p style="margin:6px 0 0;font-size:12px;color:#4f6b78">${esc(j.ref)}</p>
  </div>`).join('');

const html = `<!doctype html><html><body style="margin:0;background:#eef4f7;font-family:Arial,Helvetica,sans-serif;color:#10303b">
<div style="max-width:560px;margin:0 auto;padding:24px 16px">
  <div style="background:#10303b;color:#eef4f7;border-radius:20px;padding:22px 24px">
    <p style="margin:0;font-size:22px;font-weight:bold">${esc(r.is_update ? 'Schedule changed' : 'Tomorrow\'s jobs')}</p>
    <p style="margin:6px 0 0;font-size:28px;font-weight:bold;color:#f2b33d">${esc(day)}</p>
    <p style="margin:2px 0 0;color:#c3d6df;font-size:14px">${jobs.length} job${jobs.length === 1 ? '' : 's'}</p>
  </div>
  <div style="background:#ffffff;border-radius:20px;padding:20px 24px;margin-top:12px;font-size:15px;line-height:1.5">
    <p style="margin:0">${esc(intro)}</p>
    ${cards}
    <p style="margin:16px 0 0">Mark each job done in the technician page when you finish. Questions? Call the office at ${esc(r.business_phone)}.</p>
  </div>
  <p style="color:#4f6b78;font-size:12px;margin:16px 4px 0">${esc(r.business_name)}. This is a demo business for an AI automation project.</p>
</div></body></html>`;

return { json: { schedule_id: r.schedule_id, to_email: r.to_email, subject, html } };
